import React from "react";

const Header = ({ isAdmin, onLoginClick, onLogout }) => {
  return (
    <header className="app-header">
      <div className="header-left">
        <div className="brand">
          <span className="brand-emoji">🚗</span>
          <div>
            <div className="brand-title">Parking Dashboard</div>
            <div className="brand-sub">Level G — MyMall Smart Parking</div>
          </div>
        </div>
      </div>

      <div className="header-right">
        <div className="live-admin">
          <div className="live-pill">
            <span className="live-dot" /> Live Updating
          </div>

          {!isAdmin ? (
            <button className="btn-admin" onClick={onLoginClick}>
              Admin Login
            </button>
          ) : (
            <>
              <a className="btn-header" href="/dashboard">Dashboard</a>
              <a className="btn-header" href="/logs">Logs</a>
              <a className="btn-header" href="/analytics">Analytics</a>
              <button className="btn-logout" onClick={onLogout}>Logout</button>
            </>
          )}
        </div>
      </div>
    </header>
  );
};

export default Header;
